import sys

def can_finish_brute(n, edges):
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[b].append(a)
    state = [0] * n
    def dfs(u):
        state[u] = 1
        for v in adj[u]:
            if state[v] == 1:
                return False
            if state[v] == 0 and not dfs(v):
                return False
        state[u] = 2
        return True
    for i in range(n):
        if state[i] == 0 and not dfs(i):
            return False
    return True

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0]); m = int(data[1])
    edges = []
    idx = 2
    for _ in range(m):
        a = int(data[idx]); b = int(data[idx + 1]); idx += 2
        edges.append((a, b))
    print('true' if can_finish_brute(n, edges) else 'false')
